from copy import deepcopy


def select_rows(rows: list[dict], computed: dict, predicate=None,
                fields: tuple[str, ...] | None = None) -> list[dict]:
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    if not isinstance(computed, dict):
        raise TypeError("computed must be a dictionary")
    if predicate is not None and not callable(predicate):
        raise TypeError("predicate must be callable or None")
    if fields is not None and not isinstance(fields, tuple):
        raise TypeError("fields must be a tuple or None")

    for name, function in computed.items():
        if not isinstance(name, str):
            raise TypeError("computed names must be strings")
        if not name:
            raise ValueError("computed names cannot be empty")
        if not callable(function):
            raise TypeError("computed values must be callable")

    if fields is not None:
        seen = set()
        for field in fields:
            if not isinstance(field, str):
                raise TypeError("fields must contain strings")
            if not field:
                raise ValueError("field names cannot be empty")
            if field in seen:
                raise ValueError("fields cannot contain duplicates")
            seen.add(field)

    result = []
    for source in rows:
        if not isinstance(source, dict):
            raise TypeError("rows must contain dictionaries")
        if any(name in source for name in computed):
            raise ValueError("computed name collides with an original field")
        row = deepcopy(source)
        if predicate is not None and not predicate(row):
            continue
        for name, function in computed.items():
            row[name] = function(row)
        if fields is None:
            result.append(deepcopy(row))
        else:
            result.append({field: deepcopy(row[field]) for field in fields})
    return result
